// Concatenates supabase/migrations/*.sql into supabase/setup.sql, to paste once into
// the Supabase SQL editor (or use `supabase db push` with the CLI instead).
import { readdirSync, readFileSync, writeFileSync } from "node:fs"

const dir = new URL("../supabase/migrations/", import.meta.url)
const files = readdirSync(dir).filter((f) => f.endsWith(".sql")).sort()
const sql = [
  "-- Tilo database setup. Generated by scripts/build-setup-sql.ts; edit the migrations instead.",
  "-- Paste this whole file into Supabase → SQL Editor → New query → Run (once, on a new project).",
  "",
  ...files.map((f) => `-- ============================================================\n-- ${f}\n-- ============================================================\n\n${readFileSync(new URL(f, dir), "utf8")}`),
].join("\n")
writeFileSync(new URL("../supabase/setup.sql", import.meta.url), sql)
console.log(`supabase/setup.sql: ${files.length} migrations, ${sql.length.toLocaleString()} chars`)
